process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const TOK=process.env.GH_TOKEN||''; const REPO=process.env.GH_REPO||'raimis079-creator/petshop-bridge';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from(process.env.WP_USER+':'+process.env.WP_APP_PASS).toString('base64');
const B64='';
const PAK=JSON.parse(Buffer.from('','base64').toString('utf8'));
const out={versija:'H037'};
async function put(path,buf,msg){
  let sha=null;
  try{const g=await fetch(`https://api.github.com/repos/${REPO}/contents/${path}`,{headers:{'Authorization':'Bearer '+TOK,'User-Agent':'b'}});if(g.status===200)sha=(await g.json()).sha;}catch(e){}
  const b={message:msg,content:buf.toString('base64')}; if(sha) b.sha=sha;
  return (await fetch(`https://api.github.com/repos/${REPO}/contents/${path}`,{method:'PUT',headers:{'Authorization':'Bearer '+TOK,'Content-Type':'application/json','User-Agent':'b'},body:JSON.stringify(b)})).status;
}
async function api(p,o={}){ const r=await fetch(WP+p,{...o,headers:{Authorization:AUTH,'Content-Type':'application/json',...(o.headers||{})}}); return {s:r.status,t:await r.text()}; }
let snipId=null;
try{
  const ls=await api('/wp-json/code-snippets/v1/snippets');
  let sar=[]; try{sar=JSON.parse(ls.t);}catch(e){}
  for(const s of (Array.isArray(sar)?sar:[])){
    if(String(s.name||'').startsWith('TEMP') && s.active){
      await api('/wp-json/code-snippets/v1/snippets/'+s.id,{method:'POST',body:JSON.stringify({id:s.id,active:false})});
    }
  }
  const code=Buffer.from(B64,'base64').toString('utf8');
  const cr=await api('/wp-json/code-snippets/v1/snippets',{method:'POST',body:JSON.stringify({name:'TEMP H037 meta ir tekstu taisymai',code,scope:'global',active:true,priority:5})});
  let j=null; try{j=JSON.parse(cr.t);}catch(e){}
  snipId=j?j.id:null; out.snip=snipId||('KLAIDA '+cr.s+' '+cr.t.slice(0,200));
  await new Promise(r=>setTimeout(r,9000));

  const rk=await fetch(WP+'/?ps_h037=KOPIJA'); const tk=await rk.text();
  try{ out.kopija=JSON.parse(tk); }catch(e){ out.kopija_zalias=tk.slice(0,300); }
  if(!out.kopija || out.kopija.kopija==='NEPAVYKO'){ out.NUTRAUKTA='kopija nepadaryta'; }
  else {
    out.tekstu_rasymas={ok:0,klaidos:[]};
    for(const [tid,txt] of Object.entries(PAK)){
      const r=await api('/wp-json/wc/v3/products/categories/'+tid,{method:'PUT',body:JSON.stringify({description:txt})});
      if(r.s===200) out.tekstu_rasymas.ok++; else out.tekstu_rasymas.klaidos.push({tid,http:r.s});
      await new Promise(s=>setTimeout(s,150));
    }
    const rm=await fetch(WP+'/?ps_h037=META'); const tm=await rm.text();
    try{ out.meta=JSON.parse(tm); }catch(e){ out.meta_zalias=tm.slice(0,300); }
    await new Promise(r=>setTimeout(r,3000));
    const rp=await fetch(WP+'/?ps_h037=PATIKRA'); const tp=await rp.text();
    try{ out.patikra=JSON.parse(tp); }catch(e){ out.patikra_zalias=tp.slice(0,400); }

    /* GYVA patikra: ar meta realiai isvedamas <head> */
    out.gyvai={};
    for(const [zyme,u,laukt] of [
      ['kraikai','https://dev.avesa.lt/kategorija/katems/kraikai-kaciu-tualetams/',null],
      ['sausas','https://dev.avesa.lt/kategorija/sunims/maistas-sunims/sausas-maistas-sunims/',null]]){
      try{
        const x=await fetch(u); const h=await x.text();
        const mm=h.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i);
        out.gyvai[zyme]={http:x.status, meta:mm?mm[1]:'', ilg:mm?mm[1].length:0};
      }catch(e){ out.gyvai[zyme]={kl:String(e).slice(0,80)}; }
    }
  }
}catch(e){ out.klaida=String(e).slice(0,500); }
try{ if(snipId) await api('/wp-json/code-snippets/v1/snippets/'+snipId,{method:'POST',body:JSON.stringify({id:snipId,active:false})}); }catch(e){}
const zlib=await import('zlib');
await put('screenshots/h037.json.gz', zlib.gzipSync(Buffer.from(JSON.stringify(out))), 'h037 meta ir tekstu taisymai');
